            var c;
            var result;
            var key;
            whitespace();
            c = text.charAt(position);
            if (c === '"') { return stringValue(); }
            if (c === "-" || digit(c)) { return numberValue(); }
            if (c === "{" || c === "[") {
                var isObject = c === "{";
                var close = isObject ? "}" : "]";
                result = isObject ? {} : [];
                position++;
                whitespace();
                if (text.charAt(position) === close) { position++; return result; }
                while (true) {
                    whitespace();
                    if (isObject) {
                        if (text.charAt(position) !== '"') { fail(); }
