function (s) {
        return String(s)
            .replace(/\\/g, "\\\\")
            .replace(/"/g, "\\\"")
            .replace(/\r/g, "\\r")
            .replace(/\n/g, "\\n")
            .replace(/\t/g, "\\t")
            .replace(/[\x00-\x1f]/g, function (ch) {
                // CR/LF/TAB above retain their existing short escape spelling.
                var hex = ch.charCodeAt(0).toString(16);
                return "\\u" + ("0000" + hex).slice(-4);
            });
    }

